var input = $input.first().json;
var form = (input && typeof input.body === 'object' && input.body !== null && Object.keys(input.body).length > 0) ? input.body : input;
var text = form.text || '';
var preserveLinebreaks = form.preserve_linebreaks !== false;

if (!text.trim()) {
  return [{ json: { humanized_text: '', orig_word_count: 0, new_word_count: 0, words_added: 0, orig_sentence_count: 0, new_sentence_count: 0, sentences_added: 0 } }];
}

// --- Citation Protection ---
var CITATION_RE = /\(\s*[A-Za-z&\-,.\s]+(?:et al\.\s*)?,\s*\d{4}(?:,\s*(?:pp?\.\s*\d+(?:-\d+)?))?\s*\)/g;
var placeholderMap = {};
var protectedText = text.replace(CITATION_RE, function(match) {
  var key = '[[REF_' + (Object.keys(placeholderMap).length + 1) + ']]';
  placeholderMap[key] = match;
  return key;
});

// --- Contraction Expansion ---
var CONTRACTIONS = {
  "can't": "cannot", "won't": "will not", "shan't": "shall not",
  "ain't": "is not", "i'm": "i am", "it's": "it is",
  "we're": "we are", "they're": "they are", "you're": "you are",
  "he's": "he is", "she's": "she is", "that's": "that is",
  "there's": "there is", "what's": "what is", "who's": "who is",
  "let's": "let us", "didn't": "did not", "doesn't": "does not",
  "don't": "do not", "couldn't": "could not", "shouldn't": "should not",
  "wouldn't": "would not", "isn't": "is not", "aren't": "are not",
  "weren't": "were not", "hasn't": "has not", "haven't": "have not",
  "hadn't": "had not", "mustn't": "must not", "needn't": "need not",
  "i've": "i have", "you've": "you have", "we've": "we have",
  "they've": "they have", "i'd": "i would", "you'd": "you would",
  "he'd": "he would", "she'd": "she would", "we'd": "we would",
  "they'd": "they would", "i'll": "i will", "you'll": "you will",
  "he'll": "he will", "she'll": "she will", "we'll": "we will",
  "they'll": "they will", "it'll": "it will"
};

function expandContractions(sentence) {
  return sentence.replace(/\b(\w+)(n't|'re|'s|'ll|'ve|'d|'m)\b/gi, function(match, base, suffix) {
    var key = base.toLowerCase() + suffix.toLowerCase();
    var expanded = CONTRACTIONS[key];
    if (expanded) {
      return base.charAt(0).toUpperCase() === base.charAt(0) ? expanded.charAt(0).toUpperCase() + expanded.slice(1) : expanded;
    }
    return match;
  });
}

// --- Academic Transitions ---
var TRANSITIONS = [
  "Moreover,", "Additionally,", "Furthermore,", "Hence,",
  "Therefore,", "Consequently,", "Nonetheless,", "Nevertheless,",
  "In contrast,", "On the other hand,", "In addition,", "As a result,",
  "Similarly,", "Likewise,", "However,", "Meanwhile,"
];

function addTransition(sentence, pTrans) {
  if (Math.random() < pTrans) {
    var t = TRANSITIONS[Math.floor(Math.random() * TRANSITIONS.length)];
    return t + ' ' + sentence;
  }
  return sentence;
}

function countWords(s) { return s.split(/\s+/).filter(function(w) { return w.length > 0; }).length; }
function countSentences(s) { var count = 0; var inSentence = false; for (var i = 0; i < s.length; i++) { if ('.!?'.indexOf(s.charAt(i)) >= 0) { inSentence = true; } else if (inSentence && s.charAt(i) !== ' ') { count++; inSentence = false; } } if (inSentence) count++; return count; }

function humanizeLine(line, pTrans) {
  var result = expandContractions(line);
  result = addTransition(result, pTrans);
  return result;
}

// --- Process ---
var origWC = countWords(protectedText);
var origSC = countSentences(protectedText);

var humanized;
if (preserveLinebreaks) {
  var lines = protectedText.split('\n');
  var outLines = [];
  for (var i = 0; i < lines.length; i++) {
    if (!lines[i].trim()) { outLines.push(''); continue; }
    outLines.push(humanizeLine(lines[i], 0.2));
  }
  humanized = outLines.join('\n');
} else {
  var parts = protectedText.split(/([.!?]+\s*)/);
  var result = '';
  for (var j = 0; j < parts.length; j++) {
    if (parts[j] && parts[j].trim()) {
      result += humanizeLine(parts[j], 0.2);
    } else {
      result += (parts[j] || '');
    }
  }
  humanized = result;
}

// --- Restore Citations ---
var finalText = humanized;
for (var placeholder in placeholderMap) {
  finalText = finalText.split(placeholder).join(placeholderMap[placeholder]);
}

// --- Normalize Spacing ---
finalText = finalText.replace(/[ \t]+([.,;:!?])/g, '$1');
finalText = finalText.replace(/\([ \t]+/g, '(');
finalText = finalText.replace(/[ \t]+\)/g, ')');
finalText = finalText.replace(/[ \t]{2,}/g, ' ');

var newWC = countWords(finalText);
var newSC = countSentences(finalText);

return [{
  json: {
    humanized_text: finalText,
    orig_word_count: origWC,
    new_word_count: newWC,
    words_added: newWC - origWC,
    orig_sentence_count: origSC,
    new_sentence_count: newSC,
    sentences_added: newSC - origSC
  }
}];
